using UnityEngine;
public class WoodlandWatch:MonoBehaviour {
 public WoodlandPlayer player;public Renderer[] screens;public float chemicalConcentration;public string status="offline";public float nearestMotion=-1;public float period;float scan;bool previousLink;MaterialPropertyBlock block;
 public static float Pulse(float distance){if(distance<0||distance>100)return 0;if(distance<=5)return .12f;if(distance<=10)return .25f;if(distance<=50)return .7f;return 1.8f;}
 public static Color Signal(bool linked,float scan,float distance,float chemical,float clock){if(!linked||scan>0)return new Color(.008f,.02f,.012f);float period=Pulse(distance);if(period<=0&&chemical>0)period=Mathf.Lerp(2,.85f,Mathf.Clamp01(chemical));if(period<=0||clock%period>=period*.42f)return new Color(.008f,.02f,.012f);return distance>=0&&distance<=5?new Color(1,.025f,.035f):new Color(.04f,1,.17f);}
 void LateUpdate(){if(!player)return;var warning=player.GetComponent<WoodlandMedicalWarning>();if(warning&&warning.Active){status="danger";period=warning.Period;Show(Time.time%period<period*.4f?new Color(1,.01f,.015f):new Color(.018f,.001f,.001f));return;}bool linked=player.serviced&&Vector3.Distance(player.transform.position,player.sensor.position)<=150;if(linked!=previousLink){scan=3;previousLink=linked;}scan=Mathf.Max(0,scan-Time.deltaTime);status=scan>0?"connecting":linked?"connected":"offline";nearestMotion=-1;if(linked&&scan<=0){var companion=Object.FindFirstObjectByType<WoodlandCompanion>();if(companion&&companion.speed>.25f)Consider(companion.transform.position);if(player.creature&&player.creature.gameObject.activeInHierarchy)Consider(player.creature.position);}period=Pulse(nearestMotion);Show(Signal(linked,scan,nearestMotion,chemicalConcentration,Time.time));}
 void Consider(Vector3 point){if(Vector3.Distance(point,player.sensor.position)>100)return;float d=Vector3.Distance(point,player.transform.position);if(d<=100&&(nearestMotion<0||d<nearestMotion))nearestMotion=d;}
 public void Show(Color color){if(block==null)block=new MaterialPropertyBlock();block.SetColor("_BaseColor",color);block.SetColor("_EmissionColor",color*1.8f);foreach(var r in screens)if(r)r.SetPropertyBlock(block);}
}
